'use client';

// Generated by the Matter editor probe (MAT-96 spike). A bare Matter
// component: mount it inside a ShaderScene. Fields are functions of the
// sample position — warping is calling a field at a shifted point — and
// every editor dial arrived below as a prop with the editor's value as its
// default.
import { useEffect } from 'react';

import { colorRamp, displace, elapsedTime, simplexNoise } from '@lovo/matter';
import { useShaderContext } from '@lovo/matter-react';
import { parseColorString } from '@lovo/matter/color';
import { clamp, cos, dot, sin, uniform, uv, vec2, vec3 } from 'three/tsl';
import type { ShaderNodeObject } from 'three/tsl';
import { Mesh, MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import type { Node } from 'three/webgpu';

type TSLNode = ShaderNodeObject<Node>;

export interface GeneratedShaderProps {
  /** Gradient angle, 0 to 360. Defaults to 45. */
  gradientAngle?: number;
  /** Noise scale, 0.5 to 10. Defaults to 3. */
  noiseScale?: number;
  /** Noise speed, 0 to 1. Defaults to 0.15. */
  noiseSpeed?: number;
  /** Warp amount, 0 to 1. Defaults to 0.35. */
  warpAmount?: number;
}

export function GeneratedShader({
  gradientAngle = 45,
  noiseScale = 3,
  noiseSpeed = 0.15,
  warpAmount = 0.35,
}: GeneratedShaderProps) {
  const shaderContext = useShaderContext();

  useEffect(() => {
    if (!shaderContext) return;

    // Dials ride uniforms. This generated component rebuilds its material on
    // prop change (the deps below), which is spike shorthand — the registry
    // pattern pushes new values through stable uniforms instead.
    const gradientAngleUniform = uniform(gradientAngle);
    const noiseScaleUniform = uniform(noiseScale);
    const noiseSpeedUniform = uniform(noiseSpeed);
    const warpAmountUniform = uniform(warpAmount);

    // Directional ramp: project the centered point onto the angle's direction.
    const gradientRadians = gradientAngleUniform.mul(Math.PI / 180);
    const gradientDirection = vec2(cos(gradientRadians), sin(gradientRadians));
    const gradientField = (p: TSLNode) => clamp(dot(p.sub(0.5), gradientDirection).add(0.5), 0, 1);

    // 3D simplex with time on z: the pattern morphs in place. Raw noise
    // spans roughly -1..1; the add/mul rescales it to 0..1.
    const noiseField = (p: TSLNode) =>
      simplexNoise(vec3(p.mul(noiseScaleUniform), elapsedTime.mul(noiseSpeedUniform)))
        .add(1)
        .mul(0.5);

    // Domain warp: two far-apart taps of the driver become the x/y of a
    // push vector; the source is then read at the pushed position.
    const warpField = (p: TSLNode) => {
      const pushX = noiseField(p).sub(0.5);
      const pushY = noiseField(displace(p, vec2(5.2, 1.3))).sub(0.5);

      return gradientField(displace(p, vec2(pushX, pushY).mul(warpAmountUniform)));
    };

    // The door from pattern to color: the field picks a position along
    // the ramp, mixed in oklab.
    const rampStops = [
      { position: 0, color: vec3(...parseColorString('#1B2A6B')) },
      { position: 0.5, color: vec3(...parseColorString('#7C3AED')) },
      { position: 1, color: vec3(...parseColorString('#F472B6')) },
    ];
    const rampColor = colorRamp(warpField(uv()), rampStops, 'oklab');

    const material = new MeshBasicNodeMaterial();

    material.colorNode = rampColor;

    const mesh = new Mesh(new PlaneGeometry(2, 2), material);

    shaderContext.scene.add(mesh);
    shaderContext.scheduler.requestRender();

    return () => {
      shaderContext.scene.remove(mesh);
      try {
        material.dispose();
      } catch {
        // three/webgpu can throw during dispose under Strict Mode double-invoke
      }
      try {
        mesh.geometry.dispose();
      } catch {
        // same
      }
    };
  }, [shaderContext, gradientAngle, noiseScale, noiseSpeed, warpAmount]);

  return null;
}
